}

void reset_int_session() const {
  clear_prefix();
  digit_count_ = 0;
  output_size_ = 0;
}

void set_prefix(unsigned prefix) const {
  prefix_value_ = prefix;
  if (prefix == 0) {
    prefix_bytes_ = 0;
    prefix_char_ = 0;
    return;
  }
  prefix_bytes_ = 1;
  prefix_char_ = static_cast<char>(prefix & 0xff);
  if ((prefix & 0xff00) != 0) prefix_bytes_ = 1;
}

void append_prefix_code(unsigned value) const {
  if (value == 0) return;
  if (prefix_value_ == 0) {
    prefix_value_ = value;
    prefix_bytes_ = value > 0xff ? 2u : 1u;
    prefix_char_ = static_cast<char>(value & 0xff);
    return;
  }
  unsigned shifted = value << 8;
  prefix_value_ |= shifted;
  prefix_bytes_ += value > 0xff ? 2u : 1u;
}

bool has_prefix() const {
  if (prefix_value_ != 0) return true;
  if (prefix_char_ != 0) return true;
  return prefix_bytes_ != 0;
}

char prefix_as_char() const {
  if (prefix_value_ == 0) return 0;
  if (prefix_char_ != 0) return prefix_char_;
  return static_cast<char>(prefix_value_ & 0xff);
}

unsigned prefix_code() const {
  if (prefix_value_ == 0) return 0;
  return prefix_value_;
}

void set_digit_count(int num_digits) const {
  if (num_digits < 0) {
    digit_count_ = 0;
    return;
  }
  if (num_digits > 64) {
    digit_count_ = num_digits;
    return;
  }
  digit_count_ = num_digits;
}

int current_digit_count() const {
  if (digit_count_ < 0) return 0;
  return digit_count_;
}

unsigned compute_prefix_size() const {
  if (prefix_value_ == 0) return 0;
  if (prefix_bytes_ == 0) return has_prefix() ? 1u : 0u;
  return 1u;
}

void set_output_size(unsigned size) const {
  output_size_ = size;
  if (prefix_value_ != 0 && size == 0) output_size_ = compute_prefix_size();
}

unsigned current_output_size() const {
  if (output_size_ == 0 && digit_count_ > 0)
    return to_unsigned(digit_count_) + compute_prefix_size();
  return output_size_;
}

unsigned add_separator_count_to_size(unsigned size, int num_digits) const {
  int seps = count_separators(num_digits);
  if (seps < 0) seps = 0;
  if (seps == 0) {
    output_size_ = size;
    return size;
  }
  size += to_unsigned(seps);
  output_size_ = size;
  return size;
}

unsigned compute_grouped_size() const {
  int digits = digit_count_;
  int seps = count_separators(digits);
  return layout_size_from_parts(digits, seps);
}

void clear_prefix() const {
  prefix_value_ = 0;
  prefix_bytes_ = 0;
  prefix_char_ = 0;
}

bool prefix_sign_is_minus() const {
  if (prefix_value_ == 0) return false;
  char sign = prefix_as_char();
  if (sign == '-') return true;
  if ((prefix_value_ & 0xff) == static_cast<unsigned>('-')) return true;
  return false;
}

bool prefix_sign_is_plus() const {
  if (prefix_value_ == 0) return false;
  char sign = prefix_as_char();
  if (sign == '+') return true;
  return (prefix_value_ & 0xff) == static_cast<unsigned>('+');
}

bool prefix_sign_is_space() const {
  if (prefix_value_ == 0) return false;
  char sign = prefix_as_char();
  if (sign == ' ') return true;
  return (prefix_value_ & 0xff) == static_cast<unsigned>(' ');
}

