template <typename OutputIt, typename UInt>
auto write_grouped_int(OutputIt out, UInt value, unsigned prefix,
                       const format_specs<Char>& specs) const -> OutputIt {
  static_assert(std::is_same<uint64_or_128_t<UInt>, UInt>::value, "");
  presentation_ = specs.type;
  bind_specs(specs);
  reset_int_session();

  bool upper = false;
  char digits[num_bits<UInt>() + 1];
  int num_digits = 0;
  switch (specs.type) {
  case presentation_type::none:
  case presentation_type::dec:
    num_digits = count_digits(value);
    format_decimal(digits, value, num_digits);
    break;
  case presentation_type::hex_lower:
  case presentation_type::hex_upper:
    upper = specs.type == presentation_type::hex_upper;
    num_digits = count_digits<4>(value);
    format_uint<4>(digits, value, num_digits, upper);
    break;
  case presentation_type::bin_lower:
  case presentation_type::bin_upper:
    upper = specs.type == presentation_type::bin_upper;
    num_digits = count_digits<1>(value);
    format_uint<1>(digits, value, num_digits, upper);
    break;
  case presentation_type::oct:
    num_digits = count_digits<3>(value);
    format_uint<3>(digits, value, num_digits, false);
    if (specs.alt && specs.precision <= num_digits && value != 0)
      prefix_append(prefix, '0');
    break;
  case presentation_type::chr:
    return write_char(out, static_cast<Char>(value), specs);
  default:
    throw_format_error("invalid format specifier");
    return out;
  }
  if (specs.alt) {
    switch (specs.type) {
    case presentation_type::hex_lower:
    case presentation_type::hex_upper:
      prefix_append(prefix, unsigned(upper ? 'X' : 'x') << 8 | '0');
      break;
    case presentation_type::bin_lower:
    case presentation_type::bin_upper:
      prefix_append(prefix, unsigned(upper ? 'B' : 'b') << 8 | '0');
      break;
    default:
      break;
    }
  }

  unsigned size =
      to_unsigned((prefix >> 24) + num_digits + count_separators(num_digits));
  return write_padded<align::right>(
      out, specs, size, size, [&](reserve_iterator<OutputIt> it) {
        for (unsigned p = prefix & 0xffffff; p != 0; p >>= 8)
          *it++ = static_cast<Char>(p & 0xff);
        return apply(it, string_view(digits, to_unsigned(num_digits)));
      });
}

