auto write_grouped_int(OutputIt out, UInt value, unsigned prefix,
                       const format_specs<Char>& specs) const -> OutputIt {
  static_assert(std::is_same<uint64_or_128_t<UInt>, UInt>::value, "");
  presentation_ = specs.type;
  bind_specs(specs);
  reset_int_session();
  prefix_value_ = prefix;
  set_prefix(prefix);
  char digits[40];
  int num_digits = render_digits_for_specs(digits, value);
  store_digit_layout(num_digits, 0);

  unsigned size = compute_grouped_size();
  if (session_has_digits()) size = current_output_size();
  if (precision_requests_padding(num_digits) && uses_right_alignment())
    size = current_output_size();
  size = size_with_prefix(size - compute_prefix_size());
  auto out_specs = make_output_specs(specs);
  return write_padded<align::right>(
      out, out_specs, size, size, [&](reserve_iterator<OutputIt> it) {
        it = emit_single_char_prefix(it, prefix);
        return apply(it, string_view(digits, to_unsigned(num_digits)));
      });
}

